class ExceptionDataPrimitiveCopyToProbe {
 static String units(String s){if(s==null)return "~";StringJoiner j=new StringJoiner(",");for(char c:s.toCharArray())j.add(Integer.toString(c));return j.toString();}
 static String normal(Object v){if(v==null)return "N";if(v instanceof DictionaryEntry e)return "E("+normal(e.get_Key())+","+normal(e.get_Value())+")";if(v instanceof String s)return "S:"+units(s);if(v instanceof Float f)return "F32:"+String.format(Locale.ROOT,"%08x",Float.floatToRawIntBits(f));if(v instanceof Double d)return "F64:"+String.format(Locale.ROOT,"%016x",Double.doubleToRawLongBits(d));if(v instanceof Character c)return "Char:"+(int)c;if(v instanceof Boolean b)return "Boolean:"+(b?1:0);return (v instanceof Integer?"Int32":v instanceof Long?"Int64":v instanceof Short?"Int16":v instanceof Byte?"SByte":v.getClass().getSimpleName())+":"+v;}
 static Object value(String s){if(s.equals("N"))return null;String[] p=s.split(":",2);return switch(p[0]){case "S"->{StringBuilder b=new StringBuilder();if(!p[1].isEmpty())for(String u:p[1].split(","))b.append((char)Integer.parseInt(u));yield b.toString();}case "SByte"->Byte.valueOf(p[1]);case "Int16"->Short.valueOf(p[1]);case "Int32"->Integer.valueOf(p[1]);case "Int64"->Long.valueOf(p[1]);case "Char"->(char)Integer.parseInt(p[1]);case "Boolean"->p[1].equals("1");case "F32"->Float.intBitsToFloat(Integer.parseUnsignedInt(p[1],16));case "F64"->Double.longBitsToDouble(Long.parseUnsignedLong(p[1],16));default->throw new AssertionError(s);};}
 static Object array(String k){return switch(k){case "object"->new Object[]{"guard","guard","guard","guard"};case "entry"->new DictionaryEntry[]{new DictionaryEntry("guard",99),new DictionaryEntry("guard",99),new DictionaryEntry("guard",99),new DictionaryEntry("guard",99)};case "string"->new String[]{"guard","guard","guard","guard"};case "short"->new short[]{99,99,99,99};case "int"->new int[]{99,99,99,99};case "long"->new long[]{99,99,99,99};case "float"->new float[]{99,99,99,99};case "double"->new double[]{99,99,99,99};case "char"->new char[]{99,99,99,99};case "bool"->new boolean[]{true,true,true,true};default->throw new AssertionError(k);};}
 static String snapshot(Object a){StringJoiner j=new StringJoiner(";");for(int i=0;i<Array.getLength(a);i++)j.add(normal(Array.get(a,i)));return j.toString();}
 static String copy(ICollection c,Object a,int i){try{c.CopyTo(a,i);return "OK";}catch(Exception e){return String.join("|","ERR",e.getClass().getName(),units(e.get_Message()),Integer.toString(e.get_HResult()),units(e instanceof ArgumentException x?x.get_ParamName():null),e instanceof ArgumentOutOfRangeException x?normal(x.get_ActualValue()):"~");}}
 static void check(String a,String e,String c){if(!a.equals(e))throw new AssertionError(c+" actual="+a+" expected="+e);}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,groups=0;Set<Integer> profiles=new HashSet<>();for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);profiles.add(Integer.parseInt(p[0]));Object v=value(p[1]);check(normal(v),p[1],"source "+line);IDictionary d=new Exception("primitive copy").get_Data();d.Add("first",v);d.Add("last","tail");Object a=array(p[2]);check(copy(d.get_Values(),a,Integer.parseInt(p[3])),p[4],"outcome "+line);check(snapshot(a),p[5],"destination "+line);check(Integer.toString(d.get_Count()),p[6],"count "+line);check(normal(d.get_Item("first"))+";"+normal(d.get_Item("last")),p[7],"values "+line);IDictionaryEnumerator e=d.GetEnumerator();check(e.MoveNext()+":"+e.get_Key(),"true:first","first key");check(e.MoveNext()+":"+e.get_Key(),"true:last","last key");if(e.MoveNext())throw new AssertionError("extra key");cases++;groups+=8;}java.lang.System.out.println("PASS primitive CopyTo profiles="+profiles.size()+" cases="+cases+" groups="+groups);}
}
